"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[4297],{3695(e){e.exports=JSON.parse('{"title":"height \uc560\ub2c8\uba54\uc774\uc158, \ud558\uc9c0\ub9c8\uc138\uc694.","date":"2025-07-29","coverUrl":"/kudzu-based-bench/assets/notion/18dab5d7e29b5dd5.png","html":"<h1 data-notion-block-id=\\"237e548d-8a8e-801a-bb93-da378743d6c2\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"23de548d-8a8e-808e-a08e-ddef6bea0022\\" id=\\"23de548d-8a8e-808e-a08e-ddef6bea0022\\">height \uc560\ub2c8\uba54\uc774\uc158, \ud558\uc9c0\ub9c8\uc138\uc694.</h2><a href=\\"https://www.granola.ai/blog/dont-animate-height\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.granola.ai/blog/dont-animate-height</a><p data-notion-block-id=\\"23de548d-8a8e-8009-80e6-fb7576bba5ec\\">\uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc5d0\uc11c CPU\uc640 GPU \uc790\uc6d0\uc744 \uacc4\uc18d \uc7a1\uc544\uba39\uc5c8\ub358 \uc774\uc720\ub97c height \uae30\ubc18 \uc560\ub2c8\uba54\uc774\uc158\uc5d0\uc11c \ucc3e\uc558\uace0, \uc5b4\ub5bb\uac8c \ud574\uacb0\ud588\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \ucd5c\uadfc height \uae30\ubc18 \uc560\ub2c8\uba54\uc774\uc158\uc758 \ud3b8\uc758\uc131\uc744 \ub298\ub824\uc8fc\ub294 \uae30\ub2a5\uae4c\uc9c0 \ub098\uc654\uc9c0\ub9cc(<a href=\\"https://ones-to-watch.ethansup.net/news/post/109e548d-8a8e-8006-bd2d-e5cd889b8dc5#109e548d-8a8e-8033-a90c-e3ad6ea49f73\\"><code>height: auto;</code></a><a href=\\"https://ones-to-watch.ethansup.net/news/post/109e548d-8a8e-8006-bd2d-e5cd889b8dc5#109e548d-8a8e-8033-a90c-e3ad6ea49f73\\">\uac00 \uc560\ub2c8\uba54\uc774\uc158 \uc791\ub3d9\uc774 \uc548\ub418\uc694</a>), <a href=\\"https://developer.chrome.com/blog/performant-expand-and-collapse\\">\uc131\ub2a5\uc0c1 \uc774\uc288</a>\uac00 \uc788\uace0, \uc774\ub97c <a href=\\"https://github.com/GoogleChromeLabs/ui-element-samples/tree/gh-pages/animated-clip\\">\uc815\uacf5\ubc95\uc73c\ub85c \ud574\uacb0\ud558\uae30</a>\uc5d0\ub294 \ube44\uc6a9\uc774 \ubc1c\uc0dd\ud558\ub294 \uc810\uc740 \uc5b4\uca54 \uc218 \uc5c6\uc73c\ub2c8\uae4c\uc694.</p><h2 data-notion-block-id=\\"23de548d-8a8e-8048-afa5-e1c3e0f824c1\\" id=\\"23de548d-8a8e-8048-afa5-e1c3e0f824c1\\">React SPA\ub294 \uc5b4\ub5bb\uac8c \ub418\uace0 \uc788\uc744\uae4c</h2><a href=\\"https://www.felgus.dev/blog/future-spa\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.felgus.dev/blog/future-spa</a><p data-notion-block-id=\\"23de548d-8a8e-8048-9207-c4782c30f83f\\">\uc608\uc804\uc5d0\ub294 Render-as-you-fetch, Fetch-then-render, Fetch-on-render, Fallback Markup\u2026(\uc138\ubd80\uc801\uc73c\ub85c \ub098\ub208 \uae00\uc740 <a href=\\"https://ones-to-watch.ethansup.net/news/post/5ca5c5cc-3d5f-4c16-bb30-9df937ea2199#a176ae33-902a-4127-bd50-3ebcca67c906\\">SPA\uc5d0\uc11c \ub370\uc774\ud130\ub294 \uc5b4\ub5bb\uac8c \ubc1b\uc544\uc62c\uae4c</a>\ub97c \ucc38\uace0\ud558\uc138\uc694!), \uc5ec\ub7ec \ubc29\uc2dd\uc73c\ub85c SPA\uc5d0\uc11c \ub370\uc774\ud130\ub97c \ubc1b\uc544\uc654\uc2b5\ub2c8\ub2e4. \uadf8\ub7f0\ub370 SPA\uc758 \ubc1c\uc804\uc740 \uc5b4\ub514\ub85c \uac00\ub294 \uac83\uc77c\uae4c\uc5d0 \ub300\ud55c \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"23de548d-8a8e-8062-969c-d6d39c0553db\\" id=\\"23de548d-8a8e-8062-969c-d6d39c0553db\\">\uc131\ub2a5 \ucd5c\uc801\ud654 \uccb4\ud06c\ub9ac\uc2a4\ud2b8(2025)</h2><a href=\\"https://crystallize.com/blog/frontend-performance-checklist\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://crystallize.com/blog/frontend-performance-checklist</a><p data-notion-block-id=\\"237e548d-8a8e-8050-b53f-d19bf924abf8\\">\uc608\uc804\uc758 <a href=\\"https://ones-to-watch.ethansup.net/news/post/19523e0a-ffac-42f8-ba8e-b7bb0f77b2fa#98e76aa9-cd98-4c55-9b45-2d4e46328d94\\">\uc131\ub2a5 \ucd5c\uc801\ud654 \uccb4\ud06c\ub9ac\uc2a4\ud2b8</a> \uae00\uacfc \ube44\uc2b7\ud558\uac8c, \ud504\ub860\ud2b8\uc5d4\ub4dc\uc5d0\uc11c \uc131\ub2a5 \ucd5c\uc801\ud654\ud560 \uc218 \uc788\ub294 \ubd80\ubd84 \uc911 \uc0c1\ub2f9\uc218\ub97c \uc54c\ub824\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \ube60\ub974\uac8c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \uc131\ub2a5 \ucd5c\uc801\ud654\ub3c4 \uc788\uc9c0\ub9cc, \uc9c0\uc5fd\uc801\uc778 \ubd80\ubd84(<code>@import</code>\ub294 render-blocking \ubb38\ubc95\uc774\ub2e4, hydration cost\ub3c4 \uc8fc\uc758\ud574\uc57c \ud55c\ub2e4)\ub3c4 \uc18c\uac1c\ud558\uace0 \uc788\uc73c\ub2c8, \uac00\ubccd\uac8c \ubaa8\ub450 \ubcf4\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4. \ucd94\uac00\ub85c, <a href=\\"https://csswizardry.com/2024/08/blocking-render-why-whould-you-do-that/\\"><code>blocking=\\"render\\"</code></a><a href=\\"https://csswizardry.com/2024/08/blocking-render-why-whould-you-do-that/\\">\ub97c \uc124\uba85\ud558\uba74\uc11c render-blocking\uacfc parser-blocking\uc758 \ucc28\uc774\ub97c \uc124\uba85\ud558\ub294 \uae00</a>\ub3c4 \uc788\uc73c\ub2c8 \uac19\uc774 \ubcf4\uc2dc\uba74 \uc88b\uaca0\ub124\uc694 \ud83d\ude42</p><h2 data-notion-block-id=\\"23de548d-8a8e-8096-a512-ec471dd6d85b\\" id=\\"23de548d-8a8e-8096-a512-ec471dd6d85b\\">TypeScript\ub294 Go\ub85c \ubc14\ub010\ub2e4. Linter\ub4e4\uc740 \uc5b4\ub5bb\uac8c \ub300\ube44\ud558\uace0 \uc788\uc744\uae4c</h2><a href=\\"https://www.solberg.is/fast-type-aware-linting\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.solberg.is/fast-type-aware-linting</a><p data-notion-block-id=\\"23de548d-8a8e-808a-a25a-f91beff068a0\\">TypeScript\ub294 7\ubc84\uc804\uc5d0\uc11c Go\ub85c \ubc14\ub014 \uc900\ube44\ub97c \ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub97c \ub300\ube44\ud574\uc11c Biome \ud300\uacfc Oxlint \ud300\uc740 \uc5b4\ub5bb\uac8c \ub300\ube44\ud558\uace0 \uc788\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \uc7ac\ubc0c\uac8c\ub3c4, typescript-eslint\ud300\ub3c4 \ub300\ube44\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4(<a href=\\"https://github.com/typescript-eslint/tsgolint\\">tsgolint</a>, oxlint\ud300\uc774 fork\ud574\uc11c oxlint\uc5d0 \ub9de\uac8c \uc218\uc815\ud568.)</p><h1 data-notion-block-id=\\"237e548d-8a8e-806e-ae6a-e088711b1743\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"23de548d-8a8e-80c6-848f-f28192dcbd4e\\" id=\\"23de548d-8a8e-80c6-848f-f28192dcbd4e\\">\uce5c\uc808\ud55c SVG \uc778\ud130\ub809\ud2f0\ube0c \uac00\uc774\ub4dc</h2><a href=\\"https://www.joshwcomeau.com/svg/friendly-introduction-to-svg/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.joshwcomeau.com/svg/friendly-introduction-to-svg/</a><h2 data-notion-block-id=\\"23de548d-8a8e-80be-9e6f-ddf7b5b935eb\\" id=\\"23de548d-8a8e-80be-9e6f-ddf7b5b935eb\\">\uc815\ubcf4 \uc544\ud0a4\ud14d\uccd0 \ub610\ud55c \uc911\uc694\ud558\ub2e4.</h2><a href=\\"https://www.uxmatters.com/mt/archives/2025/07/the-hidden-cost-of-poor-navigation-how-information-architecture-directly-impacts-business-metrics.php\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.uxmatters.com/mt/archives/2025/07/the-hidden-cost-of-poor-navigation-how-information-architecture-directly-impacts-business-metrics.php</a><p data-notion-block-id=\\"23fe548d-8a8e-802e-8a6f-c476a14f5769\\">\uc815\ubcf4 \uc544\ud0a4\ud14d\uccd0(ex. \uc81c\ud488 \uc815\ucc45\uc758 \uc704\uce58)\uac00 \ube44\uc9c0\ub2c8\uc2a4 \uc9c0\ud45c\uc5d0\uc11c \uc65c \uc911\uc694\ud55c\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \uce5c\uc808\ud558\uac8c \ubcf4\uc5ec\uc92c\uc73c\uba74 \uc88b\uaca0\uc9c0\ub9cc, \uc77c\ubd80\ub7ec \uc548\ud2f0\ud328\ud134\uc73c\ub85c \uac00\ub824\ub193\uc558\uc744 \uc218\ub3c4 \uc788\ub2e4\ub294 \uc0dd\uac01\uc5d0 \uc2ac\ud504\ub124\uc694.</p><h2 data-notion-block-id=\\"23de548d-8a8e-805b-aa89-d7d3d3a0df8d\\" id=\\"23de548d-8a8e-805b-aa89-d7d3d3a0df8d\\">Storybook 9, \uc5c4\uccad\ub09c \ub2e4\uc774\uc5b4\ud2b8 \uc131\uacf5</h2><a href=\\"https://storybook.js.org/blog/storybook-bloat-fixed/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://storybook.js.org/blog/storybook-bloat-fixed/</a><p data-notion-block-id=\\"23fe548d-8a8e-8061-b634-fc95da410b92\\">\ubb3c\ub860 ESLint 9\ubc84\uc804 \ub9c8\uc774\uadf8\ub808\uc774\uc158\ucc98\ub7fc <a href=\\"https://github.com/storybookjs/storybook/issues/30944\\">\ucee4\ubba4\ub2c8\ud2f0 \ud50c\ub7ec\uadf8\uc778\uc774 \ub530\ub77c\uc624\uace0 \uc788\uc9c0 \ubabb\ud558</a>\uace0 \uc788\uc9c0\ub9cc, \ud328\ud0a4\uc9c0 \ud06c\uae30\uac00 \uc791\uc544\uc84c\ub2e4\ub294 \uac83\uc740 \uc88b\uc740 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"23de548d-8a8e-801d-8a91-d8326903260a\\" id=\\"23de548d-8a8e-801d-8a91-d8326903260a\\">\uc815\uc801 \uc0ac\uc774\ud2b8 \uc0dd\uc131\uae30, 11ty \uc0ac\uc6a9 \ud6c4\uae30</h2><a href=\\"https://etch.co/blog/we-migrated-our-site-to-eleventy-and-increased-performance-by-24-percent\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://etch.co/blog/we-migrated-our-site-to-eleventy-and-increased-performance-by-24-percent</a><h2 data-notion-block-id=\\"23de548d-8a8e-80c9-b9a6-c0b97842b526\\" id=\\"23de548d-8a8e-80c9-b9a6-c0b97842b526\\">\ud3f4\ub354\ud3f0(\uac24\ub7ed\uc2dc \ud50c\ub9bd \uc544\ub2d8) \uc2dc\uc7a5 \ud0d0\uc0c9\ud558\uae30</h2><a href=\\"https://www.smashingmagazine.com/2025/07/tiny-screens-big-impact-developing-web-apps-feature-phones/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.smashingmagazine.com/2025/07/tiny-screens-big-impact-developing-web-apps-feature-phones/</a><p data-notion-block-id=\\"239e548d-8a8e-80c2-a473-eb70f3c780c0\\">\ud3f4\ub354\ud3f0\uc744 \uc704\ud55c UI\ub294 \uc65c \ub9cc\ub4e4\uc5b4\uc57c \ud558\ub294\uc9c0, \uac04\ub2e8\ud558\uac8c \uc5b4\ub5bb\uac8c \uc9c0\uc6d0\ud560 \uc218 \uc788\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"23de548d-8a8e-80c4-9975-df1d358e8b93\\">Additional: Tech-verse 2025</h1><p data-notion-block-id=\\"23de548d-8a8e-804b-82dd-ca8e62cb36b2\\">\ud558\ub098\ub294 \uc77c\ubcf8\uc5b4 \ubc1c\ud45c\uae30\uc5d0.. \uc790\ub3d9\ubc88\uc5ed \uc790\ub9c9\uc744 \ud0a4\uace0 \ubcf4\uc2dc\ub294\uac83\uc744 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"390e548d-8a8e-8073-a0e8-e162786457e1\\" id=\\"390e548d-8a8e-8073-a0e8-e162786457e1\\">Web Vitals, \ubaa8\ub4e0 \uc0c1\ud669\uc5d0\uc11c \uc911\uc694\ud560\uae4c?</h2><a href=\\"https://www.youtube.com/watch?v=ahtRhgCPm18\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=ahtRhgCPm18</a><p data-notion-block-id=\\"23de548d-8a8e-80c3-9e9f-c732c702c726\\">LY \ub0b4\ubd80 \ub370\uc774\ud130\uc5d0\uc11c LCP, CLS, INP\uc640 CVR, \ubc14\uc6b4\uc2a4\ub960(\uc989\uc2dc\uc774\ud0c8\ub960), \uc774\ud0c8\ub960\uacfc \uc0c1\uad00\uad00\uacc4\uac00 \uc788\ub294\uc9c0 \uc9c1\uc811 \ubcf4\uc5ec\uc8fc\ub294 \ubc1c\ud45c\uc5ec\uc11c \ud765\ubbf8\ub85c\uc6cc\uc11c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. \uc0c1\uad00\uad00\uacc4\ub294 LCP\uc640 CVR\ub85c\ub9cc \uc9c1\uc811\uc801\uc73c\ub85c \ub098\ud0c0\ub0ac\uc9c0\ub9cc, \ud398\uc774\uc9c0 \uc720\ud615\ubcc4, \uc0ac\uc6a9\uc790\uc758 \ubaa9\uc801\uc774 \ubb34\uc5c7\uc774\uc600\ub294\uc9c0\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c0\ub294 \uac83\uc744 \ubcf4\uc5ec\uc900 \uac83\uc774 \uc778\uc0c1\uc801\uc774\uc600\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"390e548d-8a8e-80e2-99fe-d123158bbc8d\\" id=\\"390e548d-8a8e-80e2-99fe-d123158bbc8d\\">Next.js\uc5d0\uc11c \ub9c8\uc8fc\uce5c \ubb38\uc81c\ub4e4</h2><a href=\\"https://www.youtube.com/watch?v=ecH8Kt2DxFM\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=ecH8Kt2DxFM</a><p data-notion-block-id=\\"23de548d-8a8e-8090-a021-ffd8623216df\\">Multi tenant\ub97c \ucfe0\ubc84\ub124\ud2f0\uc2a4\uc640 \ubc30\ud3ec \uc544\ud0a4\ud14d\uccd0(ArgoCD, Helm chart)\ub97c \uc5b4\ub5bb\uac8c \uad6c\uc131\ud588\ub294\uc9c0, \uadf8\ub9ac\uace0 Next.js\ub85c \uc62e\uae30\uba74\uc11c <a href=\\"https://www.industrialempathy.com/posts/version-skew/\\">Version Skew</a> \ubb38\uc81c \ud574\uacb0(\uc640 \ub2e4\ub978 \uc7a5\uc810 \ubc0f \uc774\uc288)\uc744<b> </b>\ubcf4\uc5ec\uc8fc\ub294 \ubc1c\ud45c\uc785\ub2c8\ub2e4. \ud2b9\ud788 Node.js \uc11c\ubc84 \ub9ac\uc18c\uc2a4 \ucd5c\uc801\ud654\ub294 \uc88b\uc740 \ud301\uc774\ub124\uc694.</p><h2 data-notion-block-id=\\"23fe548d-8a8e-804d-a44f-c2fbdc64141f\\" id=\\"23fe548d-8a8e-804d-a44f-c2fbdc64141f\\">\ubc88\uc678: npm \ub77c\uc774\ube0c\ub7ec\ub9ac \ucd94\uac00\ud558\ub294 \uac83\ucc98\ub7fc DB \uc2e4\ud589\ud558\uae30</h2><a href=\\"https://endor.dev/blog/node-postgres\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://endor.dev/blog/node-postgres</a>"}')}}]);